typeDefinitions.declaration:
export interface PageHeaderBreadcrumb {
  id: string;
  label: string;
  href?: string;
}

export interface ActionDescriptor {
  id: string;
  label: string;
  disabledReason: string;
}

export interface PageHeaderProps {
  title: string;
  description?: ReactNode;
  /**
   * The trail down to this page, on one line above the title (07b board, section D row 面包屑).
   * The last crumb without an href is the current page. Inside ProductShell an omitted trail is the
   * current position in the shell's menu model.
   */
  breadcrumbs?: readonly PageHeaderBreadcrumb[];
  meta?: ReactNode;
  actions?: ActionDescriptor[] | ReactNode;
  density?: Density;
  /** Which language the trail's built-in name is said in; defaults to the page's own. */
  locale?: TcrnLocale | string;
  /**
   * The title's heading level: 2 when omitted; 1 for the page's own title, which ProductShell's
   * paper gives it unless told otherwise. Both levels set the title in the level-2 type, so the
   * level changes the outline and not the look (TCRN-DS-SUB-163).
   */
  headingLevel?: 1 | 2;
  /**
   * The name of the shell the header sits in, which tells its trail from another page header's on
   * the same page: the trail is named "{landmarkLabel} · {trail}" in the reader's language
   * (TCRN-DS-SUB-148). ProductShell passes its own `landmarkLabel`.
   */
  landmarkLabel?: string;
}

export interface ShellLocaleOption {
  locale: string;
  /** BCP 47 language tag when the product locale id uses another vocabulary. */
  lang?: string;
  nativeName: string;
}

export interface ProductShellSearchResult {
  id: string;
  title: string;
  titleKey?: string;
  meta?: string;
  metaKey?: string;
  href: string;
  selected?: boolean;
}

export interface ProductShellNavItem extends ShellMenuItem {
  labelKey?: string;
  /** The current page: the shell derives the selected row, the selected pin and the current position from it. */
  selected?: boolean;
  children?: readonly ProductShellNavItem[];
}

export interface ProductShellNavGroup extends ShellMenuGroup {
  labelKey?: string;
  descriptionKey?: string;
  sectionLabel?: string;
  sectionLabelKey?: string;
  selected?: boolean;
  items: readonly ProductShellNavItem[];
}

export interface ProductShellAccount {
  name: string;
  /** What the avatar shows; the first character of the name when omitted. */
  initials?: string;
}

export interface ProductShellProduct {
  id: string;
  label: string;
  href: string;
  /** The product this shell belongs to: aria-current="page", the 6% wash and weight 600. */
  current?: boolean;
}

export interface ProductShellNotifications {
  /** Unread notifications: more than none shows the dot and is said in the bell's name. */
  unread?: number;
  onOpen?: () => void;
}

export interface ProductShellProps extends HTMLAttributes<HTMLDivElement>, ShellSeasonalThemeOptions {
  productName: string;
  moduleName: string;
  /** The product key: the brand button's mark and wordmark and the full menu's lockup, from logos2 as they are. */
  brandProductId: TcrnProductMarkId;
  /** Name of the current page, the current position's last step when no menu entry is selected. */
  currentRouteLabel: string;
  currentRouteLabelKey?: string;
  /** The menu model: groups → items → children → children (C-7). */
  navGroups: readonly ProductShellNavGroup[];
  /** Optional right-aligned backoffice nav groups included in the menu model and pinned right group (STORY-157). */
  rightNavGroups?: readonly ProductShellNavGroup[];
  /** Explicit right-aligned backoffice pin items rendered before the right account cluster (STORY-157). */
  rightNavItems?: readonly ShellPinItem[];
  /** Ids of right-aligned backoffice entries from `navGroups` / `rightNavGroups` (STORY-157). */
  rightPinnedIds?: readonly string[];
  /** Reorder handler for the right-aligned backoffice pinned group (STORY-157). */
  onRightPinsReorder?: (orderedIds: readonly string[]) => void;
  /**
   * Optional full-width environment banner mounted between the top strip and `.tcrn-product-shell__paper`
   * with `var(--tcrn-space-3)` horizontal inset alignment; omitted or null keeps the 2-row shell grid at 0px impact (STORY-158).
   */
  topBanner?: ReactNode;
  locales: readonly ShellLocaleOption[];
  currentLocale: string;
  /** Complete product-owned copy and BCP 47 tag for currentLocale; scoped to this shell. */
  localeDefinition?: ProductShellLocaleDefinition;
  /**
   * The page's header, the paper's first row: the trail, the title and the page's actions (07b
   * board, section E, "PageHeader 必有"). Required, so a shell page without one does not type-check.
   * An omitted trail is the current position in `navGroups` (group › … › page); an omitted locale is
   * `currentLocale`; an omitted heading level is 1, the page's own title (TCRN-DS-SUB-163) — a shell
   * shown inside another page's paper gives 2.
   */
  pageHeader: PageHeaderProps;
  /** The page below its header. */
  children: ReactNode;
  currentTheme?: ShellThemeMode;
  localeMenuOpen?: boolean;
  /**
   * Product-owned controls for the top-right cluster, before the bell and the avatar, which stay
   * rightmost so their position does not move as products add controls. Omitting it renders the
   * cluster without them.
   */
  headerActions?: ReactNode;
  /** The signed-in reader; the avatar shows their initials. */
  account?: ProductShellAccount;
  /** The products the avatar menu switches between; the full menu and the lockup carry no product list. */
  products?: readonly ProductShellProduct[];
  notifications?: ProductShellNotifications;
  /** Ids of the pinned groups, items and children in the reader's order; the band shows the first six. */
  pinnedIds?: readonly string[];
  /** Pins or unpins an entry; without it the menu rows have no pin. */
  onPinnedChange?: (id: string, pinned: boolean) => void;
  /**
   * Takes the pins' new order, every id of `pinnedIds` in it, when the reader moves a pinned item
   * in the band: a drag that ends with it in a new place, or Alt+← / Alt+→ on it (TCRN-DS-SUB-149).
   * useProductShellController's productShellControlProps connect it to movePin, which keeps the
   * order in the pins preference (the product's backend through onPinsChange; never a cookie).
   * Without it the pinned items do not move.
   */
  onPinsReorder?: (orderedIds: readonly string[]) => void;
  /** Whether the full menu is open; the shell keeps its own state when omitted. */
  menuOpen?: boolean;
  /**
   * Whether ⌘K / Ctrl+K opens this shell's full menu: the key is registered on the document, once
   * per shell, so a page with several shells lets one of them have it and passes false to the
   * others. On by default (ShellMenu's `shortcut`; TCRN-DS-SUB-185).
   */
  menuShortcut?: boolean;
  onMenuOpenChange?: (open: boolean, reason: ProductShellMenuChangeReason) => void;
  /** The pinned item whose drop-down is open; the shell keeps its own state when omitted. */
  openPinId?: string | null;
  onOpenPinChange?: (id: string | null) => void;
  /** Whether the open full menu or pin drop-down takes focus. Defaults to true. */
  focusNavigationOnOpen?: boolean;
  /** The scroll frame that clips pin drop-down cascades, when the shell is embedded. */
  dropdownBoundaryRef?: RefObject<HTMLElement | null>;
  /**
   * Static states for documentation, by menu row or group id (data-tcrn-preview-state), passed to
   * the full menu and the drop-downs; a drop-down row marked "open" starts with its next level open.
   */
  previewStates?: Readonly<Record<string, string>>;
  /** Whether the avatar menu is open; the shell keeps its own state when omitted. */
  accountMenuOpen?: boolean;
  onAccountMenuOpenChange?: (open: boolean) => void;
  /** Placeholder of the full menu's search. */
  searchPlaceholder?: string;
  /** The full menu's search provider (whole-site targets); the menu model is searched when omitted. */
  searchProvider?: ShellMenuSearchProvider;
  onSearchQueryChange?: (query: string) => void;
  /**
   * A name for this shell, which tells its landmarks from another shell's on the same page (axe
   * landmark-unique): every named landmark of the shell — the band, the pinned items, the full menu
   * (panel or Sheet) and its bottom bar's trail, the drop-downs, the avatar menu and its product
   * switcher, the content region and the page header's trail — is named "{landmarkLabel} · {name}"
   * in the reader's language. A `contentLabel` or a page header's own `landmarkLabel` is used as it
   * is given. Omitted, they keep the built-in names (TCRN-DS-SUB-148, TCRN-DS-SUB-184).
   */
  landmarkLabel?: string;
  /** The full menu's query, for a product that holds it; the menu keeps its own when omitted (ShellMenu's `query`). */
  menuQuery?: string;
  /** The query the full menu's own starts from, such as a page rendered with a query typed (ShellMenu's `defaultQuery`). */
  defaultMenuQuery?: string;
  /** Asks to change the full menu's query: as it is typed, and to empty when the menu closes (ShellMenu's `onQueryChange`). */
  onMenuQueryChange?: (query: string) => void;
  /** How theme selection renders inside the avatar menu: dropdown menu when >2 themes or explicitly "menu". */
  themeControl?: "auto" | "toggle" | "menu";
  onThemeChange?: (theme: ShellThemeMode) => void;
  onLocaleMenuOpenChange?: (open: boolean, reason: ProductShellLocaleMenuChangeReason) => void;
  onLocaleChange?: (locale: string) => void;
  contentId?: string;
  contentRole?: "main" | "region";
  contentLabel?: string;
  skipLinkLabel?: string;
}

export interface TcrnShellCopy {
  /** Brand button name while the full menu is closed: pressing it opens the navigation. */
  openNavigationOf: (productName: string) => string;
  /** Brand button name while the full menu is open: pressing it closes the navigation. */
  closeNavigationOf: (productName: string) => string;
  /** Name of the pinned items group in the top band. */
  pinnedItems: string;
  /** Name of the right-aligned backoffice pinned items group in the top band (STORY-157). */
  backofficePinnedItems?: string;
  /** Screen-reader hint for pinned or menu links that open in a new window (STORY-157). */
  opensInNewWindow?: string;
  /** Default disabled reason when a shell pin or nav item is unavailable in the current role/route (STORY-157). */
  navItemUnavailable?: string;
  /** Name of the full menu (the dialog the brand button opens). */
  navigation: string;
  /** Placeholder of the full menu's search. */
  searchNavigation: string;
  /** Label of the current position in the full menu's bottom bar; also the name of that trail. */
  currentPosition: string;
  /** Title of the full menu's group of pinned items, shown narrower than 1024. */
  pinnedGroup: string;
  /** Placeholder of a drop-down's search, which searches the pinned entry's part of the menu. */
  searchWithin: (name: string) => string;
  /** Name of the avatar menu, and of the avatar when no account is given. */
  account: string;
  /** Avatar name: the reader and what the menu holds. */
  accountMenuOf: (name: string) => string;
  /** Name and heading of the avatar menu's product switcher. */
  switchProduct: string;
  /** Name of the avatar menu's theme and language controls. */
  themeAndLanguage: string;
  /** Heading of the avatar menu's user preferences section. */
  userPreferences?: string;
  /** Accessible and visible label for the theme dropdown inside user preferences. */
  themeLabel?: string;
  /** Accessible and visible label for the language dropdown inside user preferences. */
  languageLabel?: string;
  /** Theme dropdown option label for light mode. */
  themeOptionLight?: string;
  /** Theme dropdown option label for dark mode. */
  themeOptionDark?: string;
  /** Theme dropdown option label for seasonal halloween mode. */
  themeOptionHalloween?: string;
  /** Bell name, with the unread count when there is one. */
  notificationsOf: (unread: number) => string;
  /** Title of the Sheet's list of pinned entries, with their count. */
  pinnedItemsOf: (count: number) => string;
  /** Title of the Sheet's list of every group. */
  allNavigation: string;
  /** A landmark's name in one shell of several on a page: the shell's name, then the landmark's. */
  landmarkOf: (prefix: string, name: string) => string;
}

export interface ProductShellChromeCopy {
  switchToLight: string;
  switchToDark: string;
  switchToHalloween?: string;
  language: string;
  collapseSideNav: string;
  expandSideNav: string;
  /**
   * The mobile navigation control, which is a different control from the two
   * above and says a different thing.
   *
   * `collapseSideNav`/`expandSideNav` narrow the desktop rail to icons — the
   * destinations stay on screen. Below the mobile breakpoint the rail is not a
   * rail, and the same control would be a no-op, so it is hidden there; this
   * one shows and hides the navigation itself. Reusing either label would tell
   * a screen-reader user the rail is about to narrow when it is about to
   * disappear.
   */
  showNavigation: string;
  hideNavigation: string;
  breadcrumb: string;
  searchShell: string;
  searchPlaceholder: string;
  searchResults: string;
  searchEmpty: string;
  currentLocation: string;
  shellWorkspace: string;
  skipToContent: string;
  /**
   * The five with no prop behind them at all.
   *
   * A bad default at least lets a consumer pass the right string; these were
   * literals inline in the JSX, so a product shipping a ja route had no way to
   * reach them short of forking the component. Two are the only accessible name
   * their nav has.
   */
  navItemUnavailable: string;
  moduleSections: string;
  sectionNavigation: string;
  productLauncher: string;
  productSwitcher: string;
  /**
   * Two names composed from a value the consumer supplied. Concatenating an
   * English word onto a translated product or module name yields a string in
   * neither language, so the composition is per locale.
   */
  brandHomeOf: (productName: string) => string;
  shellControlsOf: (moduleName: string) => string;
  /**
   * The pin control of a NavItem or NavGroup row (TCRN-DS-SUB-123). It is icon-only,
   * so this is its whole accessible name; it says the action and the row it acts on,
   * and the action flips with the pinned state.
   */
  pinToStrip: (label: string) => string;
  unpinFromStrip: (label: string) => string;
}

export interface ProductShellCopy {
  shell: TcrnShellCopy;
  chrome: ProductShellChromeCopy;
  productTagline: (productId: TcrnProductLogoId) => string;
}

export interface ProductShellLocaleDefinition<Locale extends string = string> {
  /** Product identifier, preserved in state, preferences and callbacks (for example zh_HANT). */
  locale: Locale;
  /** BCP 47 tag for the rendered subtree (for example zh-Hant). */
  lang: string;
  copy: ProductShellCopy;
}

export interface ShellMenuItem {
  /** Stable id: the key of the row in the pin preferences, the selected id and data-pin. */
  id: string;
  /** Visible name; it truncates on one line and is repeated in the title. */
  label: string;
  /** Destination of the row. A row with a next level opens it instead of navigating. */
  href?: string;
  /** Roster icon; the full menu's columns show it, the drop-down and the cascades do not. */
  iconName?: IconName;
  /** The next level. An item's children are the third level, theirs the fourth and last. */
  children?: readonly ShellMenuItem[];
  /**
   * What the entry holds, said with its row to a screen reader (aria-describedby to a
   * .tcrn-sr-only element); nothing is drawn, and without it the row's markup is unchanged.
   */
  description?: string;
  /** Top-strip alignment when pinned (STORY-157). */
  align?: "start" | "end";
  /** External/secondary window link state (STORY-157). */
  external?: boolean;
  /** Role-gated or route-gated disabled state (STORY-157). */
  disabled?: boolean;
  /** Accessible explanation when disabled. */
  disabledReason?: string;
}

export interface ShellMenuGroup {
  id: string;
  label: string;
  /**
   * What the group (a category of the menu) holds, said to a screen reader with its title row in
   * the panel and with its row in the Sheet (aria-describedby to a .tcrn-sr-only element); nothing
   * is drawn, and without it the markup is unchanged.
   */
  description?: string;
  iconName?: IconName;
  /** Top-strip alignment inherited by pinned group/items unless overridden (STORY-157). */
  align?: "start" | "end";
  /** Role-gated or route-gated disabled state (STORY-157). */
  disabled?: boolean;
  disabledReason?: string;
  items: readonly ShellMenuItem[];
}

export interface ShellPinItem {
  /** Stable id: the key of the item in the pin preferences and in data-pin. */
  id: string;
  /** Visible name; it truncates on one line and is repeated in the title. */
  label: string;
  /** Destination of an item without a drop-down. */
  href?: string;
  /** Whether the item opens a drop-down instead of navigating. */
  hasMenu?: boolean;
  /** Placement of the pinned group in the top strip (STORY-157). */
  align?: ShellPinPlacement;
  /** Whether the link opens an external/secondary window with stroke & external indicator (STORY-157). */
  external?: boolean;
  /** Role-gated or route-gated disabled state (STORY-157). */
  disabled?: boolean;
  /** Accessible explanation when disabled. */
  disabledReason?: string;
}

example.usage:
import type { ComponentProps } from "react";
import { ProductShell, tcrnComponentCss } from "@tcrn/ui-react/approved";
import { tcrnTokenCss } from "@tcrn/ui-tokens";
import "@tcrn/ui-tokens/fonts.css";

export function Example(props: ComponentProps<typeof ProductShell>) {
  return <>
    <style>{tcrnTokenCss + "\n" + tcrnComponentCss}</style>
    <div data-tcrn-root data-tcrn-theme="light" style={{ display: "grid", gap: "var(--tcrn-space-2)" }}>
      <ProductShell {...props} />
    </div>
  </>;
}
